insert into public.english_production_paths (slug, competency_slug, skill, title, goal) values
    ('time-reference-voice-updates', 'time-and-current-relevance', 'speaking', 'Time reference in voice updates',
        'Tell a listener when something ended and distinguish it from an activity or experience that is still relevant.');

with briefs(family, stage, form, title, brief) as (values
    ('repair-shift-update', 1, 1, 'A handover from the repair room',
      'A coworker is starting the evening shift. Record a one-sentence voice update for each situation. Include the named time phrase.'),
    ('swimming-club-update', 1, 2, 'A message for the new swimming captain',
      'The new captain asks what has happened and what is still true. Record a one-sentence answer for each situation. Include the named time phrase.'),
    ('market-coordinator-update', 2, 1, 'A weekly update for a market coordinator',
      'The coordinator has been away and needs three short voice updates. Record one sentence per situation. Include the named time phrase.'),
    ('museum-volunteer-update', 2, 2, 'An update for the museum guide',
      'A guide returns for the first time this month. Record one sentence per situation to bring them up to date. Include the named time phrase.'),
    ('neighbourhood-training-update', 3, 1, 'A briefing for a new volunteer',
      'A volunteer is coming tomorrow. Leave a short voice note for each situation. Include the named time phrase.'),
    ('community-radio-update', 3, 2, 'An update for the radio producer',
      'The producer has asked for three bits of information before the programme. Record one sentence per situation. Include the named time phrase.'),
    ('office-move-update', 4, 1, 'A voice note about moving office',
      'A colleague is coming back next week and wants to know what to expect. Record one sentence per situation. Include the named time phrase.'),
    ('allotment-committee-update', 4, 2, 'A voice update for the allotment committee',
      'The committee chair is writing a short record of what happened. Record one sentence per situation. Include the named time phrase.')
), slots(family, position, prompt, anchor, accept, reject, model, explanation) as (values
    ('repair-shift-update', 1, 'Work record: back door repair, complete yesterday. Tell your coworker about the job. Use repair and yesterday.',
      '\myesterday\M', '\mrepaired\M', '\m(have|has|had|i''ve|we''ve|i''d|we''d) (already )?repaired\M',
      'I repaired the back door yesterday.', 'Yesterday names the finished period, so this event takes the simple past.'),
    ('repair-shift-update', 2, 'Workplace record: this building, May to the present. Say how long this has been your place of work. Use work and since May.',
      '\msince may\M', '\m(have|i''ve|we''ve) (worked|been working)\M', '\m(work|am working|i''m working|had worked)\M',
      'I have been working here since May.', 'The work began in May and continues now, so a present perfect form fits the update.'),
    ('repair-shift-update', 3, 'The shift is still open. Lamp checks complete: four. Give the current count. Use check and so far.',
      '\mso far\M', '\m(have|i''ve|we''ve) (already )?checked\M', '\m(check|checking|had checked)\M',
      'I have checked four lamps so far.', 'So far describes an open period. The present perfect connects the completed checks to the current tally.'),
    ('swimming-club-update', 1, 'Training venue: this club, June to today. Tell the captain how long you go there for training. Use train and since June.',
      '\msince june\M', '\m(have|i''ve|we''ve) (trained|been training)\M', '\m(train|am training|i''m training|had trained)\M',
      'I have trained there since June.', 'Since June marks the beginning of training that is still in progress.'),
    ('swimming-club-update', 2, 'Training lane reservation: complete, Friday. Tell the captain when you made it. Use book and on Friday.',
      '\mon friday\M', '\mbooked\M', '\m(have|has|had|i''ve|we''ve|i''d|we''d) (already )?booked\M',
      'I booked the training lane on Friday.', 'The booking is a finished event with a named past time.'),
    ('swimming-club-update', 3, 'Registration is ongoing. Four people are already on your list. Give the current count. Use register and so far.',
      '\mso far\M', '\m(have|i''ve|we''ve) (already )?registered\M', '\m(register|registering|had registered)\M',
      'I have registered four people so far.', 'The present tally can still change. Use the present perfect with so far.'),
    ('market-coordinator-update', 1, 'Stall move: complete last week. New position: east gate. Tell the coordinator what your team did. Use move and last week.',
      '\mlast week\M', '\mmoved\M', '\m(have|has|had|i''ve|we''ve|i''d|we''d) (already )?moved\M',
      'We moved the produce stall to the east gate last week.', 'Last week closes the time period for the move.'),
    ('market-coordinator-update', 2, 'Tea is still on the stall menu. It first went on sale there in March. Give the coordinator the timeline. Use sell and since March.',
      '\msince march\M', '\m(have|i''ve|we''ve) (sold|been selling)\M', '\m(sell|are selling|we''re selling|had sold)\M',
      'We have been selling tea at the market since March.', 'The activity links a past starting boundary to the present.'),
    ('market-coordinator-update', 3, 'This morning’s stall allocation is still in progress. There are three requests in your approved list. Use approve and so far.',
      '\mso far\M', '\m(have|i''ve|we''ve) (already )?approved\M', '\m(approve|approving|had approved)\M',
      'I have approved three requests so far.', 'The present perfect gives the number up to now, while the allocation is still open.'),
    ('museum-volunteer-update', 1, 'Visitor tours are still part of your duties. Your first tour was in September. Use show and since September.',
      '\msince september\M', '\m(have|i''ve|we''ve) (shown|been showing)\M', '\m(show|am showing|i''m showing|had shown)\M',
      'I have been showing visitors around since September.', 'Use a present perfect form for an activity that started before now and still happens.'),
    ('museum-volunteer-update', 2, 'Yesterday’s log: lobby open briefly for a private group. You were on duty. Use open and yesterday.',
      '\myesterday\M', '\mopened\M', '\m(have|has|had|i''ve|we''ve|i''d|we''d) (already )?opened\M',
      'I opened the lobby for a private group yesterday.', 'The named time is over, so use opened in the simple past.'),
    ('museum-volunteer-update', 3, 'The comment box is still open. Number of comments in your inbox: six. Give the current count. Use receive and so far.',
      '\mso far\M', '\m(have|i''ve|we''ve) (already )?received\M', '\m(receive|receiving|had received)\M',
      'We have received six comments so far.', 'The total is current and the collection period is open.'),
    ('neighbourhood-training-update', 1, 'Side gate work order: new lock, complete last Tuesday. Tell the volunteer what your team did. Use fit and last Tuesday.',
      '\mlast tuesday\M', '\m(fit|fitted)\M', '\m(have|has|had|i''ve|we''ve|i''d|we''d) (already )?(fit|fitted)\M',
      'We fitted a lock on the side gate last Tuesday.', 'Last Tuesday places the finished work in the past. Fit and fitted are both used as past forms by different English speakers.'),
    ('neighbourhood-training-update', 2, 'Volunteer record: work at the centre, April to today. Tell the volunteer how long you are involved. Use help and since April.',
      '\msince april\M', '\m(have|i''ve|we''ve) (helped|been helping)\M', '\m(help|am helping|i''m helping|had helped)\M',
      'I have been helping at the centre since April.', 'The present perfect continuous expresses the continuing activity.'),
    ('neighbourhood-training-update', 3, 'Signups are still open. Your invitation list already has eight tenants on it. Give a current count. Use invite and so far.',
      '\mso far\M', '\m(have|i''ve|we''ve) (already )?invited\M', '\m(invite|inviting|had invited)\M',
      'I have invited eight tenants so far.', 'The invitation count still has time to rise, so use the present perfect.'),
    ('community-radio-update', 1, 'Presenting rota: your name on the Saturday show, January to now. Tell the producer how long it has been your show. Use host and since January.',
      '\msince january\M', '\m(have|i''ve|we''ve) (hosted|been hosting)\M', '\m(host|am hosting|i''m hosting|had hosted)\M',
      'I have been hosting the Saturday show since January.', 'Here the start date connects a past period to a role you still have.'),
    ('community-radio-update', 2, 'Studio log: introduction, ready to use, date yesterday. Tell the producer what you did. Use record and yesterday.',
      '\myesterday\M', '\mrecorded\M', '\m(have|has|had|i''ve|we''ve|i''d|we''d) (already )?recorded\M',
      'I recorded an introduction yesterday.', 'Yesterday refers to a finished past period, so use the simple past.'),
    ('community-radio-update', 3, 'Phone lines open. The log shows five answered calls. Give a current count. Use answer and so far.',
      '\mso far\M', '\m(have|i''ve|we''ve) (already )?answered\M', '\m(answer|answering|had answered)\M',
      'We have answered five calls so far.', 'Use the present perfect for a tally that still belongs to the present period.'),
    ('office-move-update', 1, 'Key pickup: complete, Monday. Tell your colleague when you got the new office keys. Use collect and on Monday.',
      '\mon monday\M', '\mcollected\M', '\m(have|has|had|i''ve|we''ve|i''d|we''d) (already )?collected\M',
      'I collected the new office keys on Monday.', 'On Monday dates the completed action in the past.'),
    ('office-move-update', 2, 'Your regular meeting place is still the small room. Your first meeting there was in February. Use use and since February.',
      '\msince february\M', '\m(have|i''ve|we''ve) (used|been using)\M', '\m(use|am using|i''m using|had used)\M',
      'I have used the small meeting room since February.', 'Since February introduces the starting point of a use that continues.'),
    ('office-move-update', 3, 'The packing is still under way. Number of boxes sealed and ready to move: twelve. Use pack and so far.',
      '\mso far\M', '\m(have|i''ve|we''ve) (already )?packed\M', '\m(pack|packing|had packed)\M',
      'We have packed twelve boxes so far.', 'The present perfect is natural when the work is ongoing and the number is current.'),
    ('allotment-committee-update', 1, 'Water rota manager: you, from August to the present. Tell the chair about your current role. Use manage and since August.',
      '\msince august\M', '\m(have|i''ve|we''ve) (managed|been managing)\M', '\m(manage|am managing|i''m managing|had managed)\M',
      'I have been managing the water rota since August.', 'The responsibility started before now and continues.'),
    ('allotment-committee-update', 2, 'Tool shed work order: repair complete last Thursday. Tell the chair what your group did. Use repair and last Thursday.',
      '\mlast thursday\M', '\mrepaired\M', '\m(have|has|had|i''ve|we''ve|i''d|we''d) (already )?repaired\M',
      'We repaired the tool shed last Thursday.', 'The date names a closed past time for the repair.'),
    ('allotment-committee-update', 3, 'The order is open. Seven extra seed packets are on your list. Give the current number. Use add and so far.',
      '\mso far\M', '\m(have|i''ve|we''ve) (already )?added\M', '\m(add|adding|had added)\M',
      'I have added seven packets so far.', 'The count is still current while the order is open.')
)
insert into public.english_production_tasks (family, path_slug, stage, form, title, brief, rubric_version, slots)
select briefs.family, 'time-reference-voice-updates', stage, form, title, brief, 'time-reference-v1',
    jsonb_agg(jsonb_build_object('prompt', prompt, 'anchor', anchor, 'accept', accept, 'reject', reject,
        'finished', anchor not like '%since %' and anchor not like '%so far%',
        'model', model, 'explanation', explanation) order by position)
from briefs join slots on briefs.family = slots.family
group by briefs.family, stage, form, title, brief;
